mapper.select:
SELECT id AS database_id, business_id, plan_id, request_id, expert_id,
session_id, status, last_sequence
FROM digital_team_coordinator_task WHERE tenant_id = #{tenantId} AND request_id = #{requestId}

mapper.update:
UPDATE digital_team_coordinator_task SET session_id = #{sessionId}, status = 'RUNNING',
last_sequence = 0, updated_at = CURRENT_TIMESTAMP WHERE business_id = #{taskId}
AND status = 'WAITING_HUMAN'

UPDATE digital_team_coordinator_task SET status = 'RUNNING',
updated_at = CURRENT_TIMESTAMP WHERE tenant_id = #{tenantId}
AND business_id = #{taskId} AND status = 'WAITING_HUMAN'

UPDATE digital_team_coordinator_task SET status = #{status},
updated_at = CURRENT_TIMESTAMP WHERE tenant_id = #{tenantId}
AND business_id = #{taskId} AND status = 'WAITING_HUMAN'

mapper.select:
SELECT COALESCE(MAX(last_sequence), 0)
FROM digital_team_coordinator_task
WHERE session_id = #{sessionId} AND business_id <> #{taskId}

SELECT id AS database_id, business_id, plan_id, request_id, expert_id,
session_id, status, last_sequence
FROM digital_team_coordinator_task WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND business_id = #{taskId}

SELECT d.business_id FROM digital_team_coordinator_task t
JOIN digital_team_coordinator_plan p ON p.business_id = t.plan_id
JOIN digital_team_coordinator_dispatch d ON d.message_id = p.message_id
AND d.tenant_id = p.tenant_id
WHERE t.tenant_id = #{tenantId} AND t.project_id = #{projectId}
AND t.business_id = #{taskId}

SELECT t.tenant_id, t.business_id AS coordinator_task_id,
#{agentId} AS agent_id, #{agentRunId} AS agent_run_id
FROM digital_team_coordinator_task t
JOIN digital_team_coordinator_plan p ON p.business_id = t.plan_id
JOIN digital_team_project_conversation c ON c.business_id = p.conversation_id
WHERE t.project_id = #{projectId} AND p.conversation_id = #{conversationId}
AND c.session_id = #{businessSessionId} AND t.session_id = #{agentRunId}
AND t.expert_id = #{agentId}
AND t.status IN ('RUNNING', 'WAITING_HUMAN')
